// Original storage-only example: three independent keys make selected migration visible.
const host=window.clipcraftPanel,$=id=>document.getElementById(id),fields=['label','accent','density'];
function paint(){const colors={violet:'#9c80ff',amber:'#ffd06b',teal:'#62d7c2'};$('sample').style.borderColor=colors[$('accent').value];$('sample-label').style.color=colors[$('accent').value];$('sample-label').textContent=$('label').value;$('sample').style.gap=$('density').value==='compact'?'4px':'14px';}
fields.forEach(id=>$(id).addEventListener('input',paint));
(async()=>{try{const info=await host.getInfo();$('version').textContent=`Preference workbench · ${info.version}`;for(const key of fields){const value=await host.storage.get(key);if(value!==null){if(typeof value!=='string'||key==='label'&&value.length>80||key==='accent'&&!['violet','amber','teal'].includes(value)||key==='density'&&!['comfortable','compact'].includes(value))throw Error('Saved preferences are invalid. Clear saved panel data in Settings to reset them.');$(key).value=value;}}paint();$('save').disabled=false;$('status').textContent='Ready. Save preferences to keep these values for this version.';}catch(e){$('status').textContent=e.message;}})();
$('preferences').addEventListener('submit',async event=>{event.preventDefault();$('save').disabled=true;try{for(const key of fields)await host.storage.set(key,$(key).value);$('status').textContent='Preferences saved.';}catch(e){$('status').textContent=e.message;}finally{$('save').disabled=false;}});
